// ── Coffee shop example: base + decorators ────────────────────────
class Coffee {
  getCost()        { return 2.00; }
  getDescription() { return 'Espresso'; }
}

class CoffeeDecorator {
  constructor(coffee) {
    this._coffee = coffee;
  }
  getCost()        { return this._coffee.getCost(); }         // delegate
  getDescription() { return this._coffee.getDescription(); }  // delegate
}

class MilkDecorator extends CoffeeDecorator {
  getCost()        { return super.getCost() + 0.50; }
  getDescription() { return super.getDescription() + ', Milk'; }
}

class CaramelDecorator extends CoffeeDecorator {
  getCost()        { return super.getCost() + 0.75; }
  getDescription() { return super.getDescription() + ', Caramel'; }
}

class WhipDecorator extends CoffeeDecorator {
  getCost()        { return super.getCost() + 0.60; }
  getDescription() { return super.getDescription() + ', Whip'; }
}

// Assemble different combinations without new subclasses:
let order = new Coffee();
order = new MilkDecorator(order);
order = new CaramelDecorator(order);
order = new WhipDecorator(order);

console.log(order.getDescription()); // Espresso, Milk, Caramel, Whip
console.log(`$${order.getCost().toFixed(2)}`); // $3.85

// ── Middleware-style decorator: logging + timing ──────────────────
class UserService {
  getUser(id) {
    return { id, name: 'Alice', role: 'admin' };
  }
}

class LoggingDecorator {
  constructor(service) { this._service = service; }
  getUser(id) {
    console.log(`[LOG] getUser called with id=${id}`);
    const result = this._service.getUser(id);
    console.log(`[LOG] getUser returned: ${JSON.stringify(result)}`);
    return result;
  }
}

class CachingDecorator {
  constructor(service) {
    this._service = service;
    this._cache = {};
  }
  getUser(id) {
    if (this._cache[id]) {
      console.log(`[CACHE] Hit for id=${id}`);
      return this._cache[id];
    }
    const result = this._service.getUser(id);
    this._cache[id] = result;
    console.log(`[CACHE] Stored id=${id}`);
    return result;
  }
}

// Stack: CachingDecorator → LoggingDecorator → UserService
const svc = new CachingDecorator(new LoggingDecorator(new UserService()));

svc.getUser(42);
// [LOG] getUser called with id=42
// [LOG] getUser returned: {"id":42,"name":"Alice","role":"admin"}
// [CACHE] Stored id=42

svc.getUser(42);
// [CACHE] Hit for id=42  ← no log, served from cache

// ── Pure structural skeleton ─────────────────────────────────────

// 1. Component Interface
class Component {
  operation() { throw new Error('Not implemented'); }
}

// 2. Concrete Component (the real object)
class ConcreteComponent extends Component {
  operation() { return 'ConcreteComponent: base behaviour'; }
}

// 3. Base Decorator — wraps any Component
class Decorator extends Component {
  constructor(component) {
    super();
    this._component = component;
  }
  operation() {
    return this._component.operation(); // pure delegation
  }
}

// 4. Concrete Decorators — add behaviour around delegation
class ConcreteDecoratorA extends Decorator {
  operation() {
    return `DecoratorA(${super.operation()})`;
  }
}

class ConcreteDecoratorB extends Decorator {
  operation() {
    return `DecoratorB(${super.operation()})`;
  }
}

// Compose at runtime:
const base   = new ConcreteComponent();
const withA  = new ConcreteDecoratorA(base);
const withAB = new ConcreteDecoratorB(withA);

console.log(withAB.operation());
// DecoratorB(DecoratorA(ConcreteComponent: base behaviour))

